        [0,1],[1,2],[2,3],[3,0], // back
        [4,5],[5,6],[6,7],[7,4], // front
        [0,4],[1,5],[2,6],[3,7], // connectors
      ];
      ctx.strokeStyle = '#6cf';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (const [a, b] of edges) {
        const pa = project(wv[a]);
        const pb = project(wv[b]);
        ctx.moveTo(pa.x, pa.y);
        ctx.lineTo(pb.x, pb.y);
      }
      ctx.stroke();
    } else {
      // Gouraud fill pass
      for (const f of prepared) {
        const [p0, p1, p2, p3] = f.proj;
        const [c0, c1, c2, c3] = f.cols;
        // Split quad into two triangles: (0,1,2) and (0,2,3)
        fillGouraudTri(p0, p1, p2, c0, c1, c2);
        fillGouraudTri(p0, p2, p3, c0, c2, c3);
      }
    }

    // Optional: draw a small marker for the light position (projected)
    {
      const lp = project(lightPos);
      ctx.fillStyle = '#ffd54a';
      ctx.beginPath();
      ctx.arc(lp.x, lp.y, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,213,74,0.35)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(lp.x, lp.y, 11, 0, Math.PI * 2);
      ctx.stroke();
    }

    // FPS update (smoothed)
    frames++;
    const now = performance.now();
    const elapsed = now - fpsT0;
    if (elapsed >= 500) {
      fps = (frames * 1000) / elapsed;
      fpsEl.textContent = 'FPS: ' + fps.toFixed(1);
      frames = 0;
      fpsT0 = now;
    }

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
